import sys
import math

def count_nice_staircases(x):
    max_n = int(math.isqrt(2 * x)) + 2
    nice_n = []
    for n in range(1, max_n + 1):
        cells = n * (n + 1) // 2
        if cells <= x:
            nice_n.append(n)
    return len(nice_n)

def main():
